using MediatR; using OAS.Application.Abstractions.Persistence; using OAS.Application.Abstractions.Persistence.Specifications; using OAS.Application.Common.Exceptions; using OAS.Domain.Accounting.Entities;
namespace OAS.Application.Accounting.Currencies.Commands.CreateCurrency;
public sealed class CreateCurrencyCommandHandler(IRepository<Currency,Guid> repository):IRequestHandler<CreateCurrencyCommand,Guid>{public async Task<Guid> Handle(CreateCurrencyCommand r,CancellationToken ct){var code=r.Request.Code.Trim().ToUpperInvariant();if(await repository.CountAsync(new Specification<Currency>().Where(x=>x.Code==code),ct)>0)throw new ConflictException("currency_code_duplicate","Currency code already exists.");var e=Currency.Create(Guid.NewGuid(),code,r.Request.NameAr,r.Request.NameEn,r.Request.Symbol,r.Request.DecimalPlaces,r.Request.IsActive);await repository.AddAsync(e,ct);return e.Id;}}
